select
parkingSpace.*
from parking_space parkingSpace

    and parkingSpace.id = #{id}
    and parkingSpace.number = #{number}
    and parkingSpace.address = #{address}
    and parkingSpace.status = #{status}
    and parkingSpace.create_time = #{createTime}


    limit #{current},#{pageSize}

